export function setupInterface(){
 const sidebar=document.querySelector('#sidebar');if(sidebar.querySelector('.workspace-tabs'))return;
 const groups=[['explore','Keşfet',['.supplement-note','#femaleMuscleOpen','.layers-section','.opacity-section','.quick-section']],['inspect','İncele',['.study-controls','.appearance-section']],['learn','Öğren',['.learning-choice','.course-entry','.volume-entry']],['saved','Çalışma',['.personal-tools']]];
 const tabs=document.createElement('div');tabs.className='workspace-tabs';tabs.setAttribute('role','tablist');tabs.setAttribute('aria-label','Atlas araçları');
 const search=sidebar.querySelector('.search-box'),results=sidebar.querySelector('#searchResults'),model=sidebar.querySelector('.model-choice');
 const headerTools=document.createElement('div');headerTools.className='header-tools';document.querySelector('header').insertBefore(headerTools,document.querySelector('.edition'));headerTools.append(search,results,model);
 const sexSelect=model.querySelector('select'),sexToggle=document.createElement('div');sexToggle.className='sex-toggle';sexToggle.setAttribute('role','group');sexToggle.setAttribute('aria-label','Anatomi referansı');sexToggle.innerHTML='<button type="button" data-sex="female">Kadın</button><button type="button" data-sex="male">Erkek</button>';model.append(sexToggle);const syncSex=()=>sexToggle.querySelectorAll('button').forEach(b=>{const selected=b.dataset.sex===sexSelect.value;b.setAttribute('aria-pressed',String(selected));});sexToggle.addEventListener('click',e=>{const b=e.target.closest('[data-sex]');if(!b||sexSelect.disabled)return;sexSelect.value=b.dataset.sex;sexSelect.dispatchEvent(new Event('change',{bubbles:true}));});sexSelect.addEventListener('change',syncSex);syncSex();
 const nav=sidebar.querySelector('.side-heading');nav.after(tabs);
 const regions=document.createElement('nav');regions.className='region-cards';regions.setAttribute('aria-label','Vücut bölgeleri');regions.innerHTML='<button type="button" data-region="all" class="is-active"><span class="region-symbol">◉</span><span>Tüm vücut</span></button><button type="button" data-region="arm"><span class="region-symbol">↗</span><span>Omuz ve kol</span></button><button type="button" data-region="head"><span class="region-symbol">◉</span><span>Baş ve boyun</span></button><button type="button" data-region="pelvis"><span class="region-symbol">◇</span><span>Pelvis</span></button>';
 tabs.after(regions);regions.addEventListener('click',e=>{const b=e.target.closest('[data-region]');if(!b)return;regions.querySelectorAll('button').forEach(x=>x.classList.toggle('is-active',x===b));const select=document.querySelector('#region');select.value=b.dataset.region;select.dispatchEvent(new Event('change',{bubbles:true}));});
 document.querySelector('#region').addEventListener('change',e=>regions.querySelectorAll('button').forEach(b=>b.classList.toggle('is-active',b.dataset.region===e.target.value)));
 for(const [key,label,selectors] of groups){const button=document.createElement('button');button.id='tab-'+key;button.textContent=label;button.dataset.workspace=key;button.setAttribute('role','tab');button.setAttribute('aria-controls','workspace-'+key);tabs.append(button);const panel=document.createElement('div');panel.id='workspace-'+key;panel.className='workspace-panel';panel.setAttribute('role','tabpanel');panel.setAttribute('aria-labelledby',button.id);panel.tabIndex=0;for(const selector of selectors){const node=sidebar.querySelector(selector);if(node)panel.append(node);}sidebar.querySelector('.side-footer').before(panel);}
 const select=key=>{for(const button of tabs.children){const active=button.dataset.workspace===key;button.setAttribute('aria-selected',String(active));button.tabIndex=active?0:-1;document.querySelector('#'+button.getAttribute('aria-controls')).hidden=!active;}sidebar.scrollTop=0;};
 for(const button of tabs.children)button.onclick=()=>select(button.dataset.workspace);
 tabs.onkeydown=e=>{const buttons=[...tabs.children],i=buttons.indexOf(document.activeElement);if(i<0)return;let next=i;if(e.key==='ArrowRight')next=(i+1)%buttons.length;else if(e.key==='ArrowLeft')next=(i+buttons.length-1)%buttons.length;else if(e.key==='Home')next=0;else if(e.key==='End')next=buttons.length-1;else return;e.preventDefault();buttons[next].focus();select(buttons[next].dataset.workspace);};
 const saved=document.querySelector('#workspace-saved'),offline=document.createElement('section');offline.className='offline-tools';offline.innerHTML='<h2>Çevrimdışı kullanım</h2>';for(const id of ['offlineDownload','offlineStatus','installApp'])offline.append(document.getElementById(id));saved.append(offline);
 const close=document.createElement('button');close.id='closeSidebar';close.textContent='×';close.setAttribute('aria-label','Araç panelini kapat');sidebar.querySelector('.side-heading').append(close);close.onclick=()=>{sidebar.classList.remove('open');document.getElementById('mobileLayers').focus();};
 document.getElementById('mobileDetails').onclick=()=>{const panel=document.getElementById('details');panel.classList.toggle('open');sidebar.classList.remove('open');if(panel.classList.contains('open'))document.getElementById('closeDetail').focus();};
 document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!document.querySelector('dialog[open]')&&document.querySelector('#thoraxPanel').hidden){const was=sidebar.classList.contains('open');sidebar.classList.remove('open');document.getElementById('details').classList.remove('open');if(was)document.getElementById('mobileLayers').focus();}});
 select('explore');
}
export function decorateDetails(){
 const content=document.getElementById('detailContent');if(content.querySelector('.detail-jumps'))return;
 const targets=[...content.querySelectorAll('.detail-block,.detail-sources,.personal-note,.advanced-card')];
 const nav=document.createElement('nav');nav.className='detail-jumps';nav.setAttribute('aria-label','Açıklama bölümleri');
 targets.forEach((section,index)=>{const heading=section.querySelector('h3,summary');if(!heading)return;section.id='explanation-'+index;const button=document.createElement('button');button.textContent=heading.textContent.replace(/^\d+\s*/,'');if(section.classList.contains('advanced-only'))button.className='advanced-only';button.onclick=()=>{if(section.tagName==='DETAILS')section.open=true;section.scrollIntoView?.({block:'start',behavior:globalThis.matchMedia?.('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});section.tabIndex=-1;section.focus({preventScroll:true});};nav.append(button);});
 content.querySelector('.detail-actions')?.after(nav);
}
